import{_ as e,c as s,aU as n,b as t,a as l}from"./chunks/framework.DIXiA2XH.js";const b=JSON.parse('{"title":"大模型基础概念","description":"","frontmatter":{},"headers":[],"relativePath":"note/ai/ai/大模型基础概念.md","filePath":"note/ai/ai/大模型基础概念.md","lastUpdated":1782571265000}'),p={name:"note/ai/ai/大模型基础概念.md"};function o(i,a,r,u,c,d){return l(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="大模型基础概念" tabindex="-1">大模型基础概念 <a class="header-anchor" href="#大模型基础概念" aria-label="Permalink to &quot;大模型基础概念&quot;">​</a></h1><h2 id="什么是llm" tabindex="-1">什么是llm <a class="header-anchor" href="#什么是llm" aria-label="Permalink to &quot;什么是llm&quot;">​</a></h2><p>简单的来说，llm就是 给定上文，预测下一个最可能的词（或子词单元，即 token）</p><p>比如你输入 “今天天气真”，模型会计算词表中每个词出现的概率，然后选一个（或按某种策略采样）作为下一个词，比如 “好”；然后拿 “今天天气真好” 再预测下一个词，比如 “啊”…… 如此循环，直到生成完整回答。</p><p>总结：LLM 生成文本时 = 循环执行“根据已生成的文本，预测下一个 token”。</p><h2 id="什么是token" tabindex="-1">什么是token <a class="header-anchor" href="#什么是token" aria-label="Permalink to &quot;什么是token&quot;">​</a></h2><p>token就是根据分词器分好的最小单元。 不同的模型 可能对同一句话有不同的分法。 每个模型在训练之前，要先“制造”一个词汇表（Vocabulary）和一个分词规则（Tokenizer）。这个规则是固定的，训练完成后就不会再变。</p><p>LLM的Token既不是一个完整的单词，也不是一个固定的汉字。它会把常见的短词、词根、甚至单个字母拆开，又能把高频组合（如“ChatGPT”中的“Chat”）合并成一个Token</p><h2 id="词表是什么" tabindex="-1">词表是什么 <a class="header-anchor" href="#词表是什么" aria-label="Permalink to &quot;词表是什么&quot;">​</a></h2><p>词表非常的重要！</p><ul><li>词表类似是一个“字典”，列出了模型所有认识的token。</li><li>LLM是根据这些token的某种“表示”来计算和预测下一个token。</li></ul>',11),t("p",{token文本:"","-":"",唯一ID:"","(整数)":""},"举个例子，比如",-1),n(`<p><strong>第一步</strong></p><p>例如GPT-4的部分词表可能是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;我&quot;: 1234,</span></span>
<span class="line"><span>  &quot;你&quot;: 5678,</span></span>
<span class="line"><span>  &quot;你好&quot;: 9012,</span></span>
<span class="line"><span>  &quot;Chat&quot;: 3456,</span></span>
<span class="line"><span>  &quot;GPT&quot;: 7890,</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>词表大小 = 模型知道多少个不同的token。比如10万、5万等。</p><p>作用：把文本变成模型能处理的数字ID。比如“你好” → 整数 9012。</p><p><strong>第二步：</strong></p><p>当模型拿到token的ID（比如9012）后，它会做一件事：去一个巨大的“查找表”里，把这个ID对应的“向量”取出来。</p><p>这个向量就是一串小数，比如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9012对应的向量 = [0.123, -0.456, 0.789, ..., 1.3234, ...]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>向量的长度（维度）通常是几百到几千，比如768维、1024维、4096维等。</p></blockquote><h2 id="llm是怎么预测下一个token的-完整流程" tabindex="-1">LLM是怎么预测下一个token的 (完整流程） <a class="header-anchor" href="#llm是怎么预测下一个token的-完整流程" aria-label="Permalink to &quot;LLM是怎么预测下一个token的 (完整流程）&quot;">​</a></h2><p>假设输入“你好”，模型要预测下一个token：</p><p><strong>步骤1：转成ID</strong></p><ul><li>“你” → ID 5678</li><li>“好” → ID 6789（假设）</li></ul><p><strong>步骤2：查表得向量</strong></p><ul><li>ID 5678 → 向量 A = [0.1, 0.2, ...]</li><li>ID 6789 → 向量 B = [0.3, 0.4, ...]</li></ul><p><strong>步骤3：加上位置编码</strong></p><ul><li>位置1（你）→ 加上位置向量P1 → 得到新向量 X1</li><li>位置2（好）→ 加上位置向量P2 → 得到新向量 X2</li></ul><p><strong>步骤4：经过Transformer的几十层计算</strong>（这是真正的“理解”过程）</p><ul><li>输入 X1, X2 → 层层传递、交互、变换 → 最后输出一个<strong>预测向量</strong> Y</li></ul><p><strong>步骤5：预测下一个token</strong></p><ul><li>预测向量 Y 的长度 = 词表大小（比如10万）</li><li>Y 中的每个数值代表词表中对应token的<strong>得分</strong>（比如第1234个token得分8.5，第5678个token得分3.2...）</li><li>用softmax函数把得分转成<strong>概率</strong>（所有概率加起来=1）</li><li>得分最高的token就是模型的“最佳猜测”</li></ul><p><strong>步骤6：输出</strong></p><ul><li>如果最高概率对应ID 9012（“你好”中的“好”已经输过了，这里假设是“吗”），那就输出“吗”</li></ul><h2 id="什么是agent" tabindex="-1">什么是Agent <a class="header-anchor" href="#什么是agent" aria-label="Permalink to &quot;什么是Agent&quot;">​</a></h2><p>其实就是 通过目标（输入）-&gt; 感知上下文 -&gt; 思考规划 -&gt; 调用工具 -&gt; 观察结果 -&gt; 自我判断 -&gt; 是否完成，如果完成了 就结束，如果没有完成，就再次循环（从感知上下文开始） 直到完成</p>`,26)])])}const g=e(p,[["render",o]]);export{b as __pageData,g as default};
